import type { DownloadFile } from '../http';
import type { OwnerBookingFilter, OwnerBookingListItem } from '../types';

/** Mock mode only: loaded on demand; real exports are generated by the backend. */
export async function createMockBookingWorkbook(
  items: OwnerBookingListItem[], filter: OwnerBookingFilter, language: string,
): Promise<DownloadFile> {
  const { default: ExcelJS } = await import('exceljs');
  const workbook = new ExcelJS.Workbook();
  const vi = language.startsWith('vi');
  const now = new Date();
  // Excel stores wall-clock dates without timezone information.
  const wallTime = (date: string | Date) => new Date(new Date(date).getTime() + 7 * 3_600_000);
  const headings = vi
    ? ['Mã booking', 'Tài xế', 'Trạm', 'Đầu sạc', 'Bắt đầu', 'Kết thúc', 'Thời lượng đặt chỗ (phút)', 'Trạng thái', 'Lý do hủy', 'Giá trị booking', 'Đơn vị tiền']
    : ['Booking code', 'Driver', 'Station', 'Connector', 'Start', 'End', 'Booked duration (minutes)', 'Status', 'Cancellation reason', 'Booking value', 'Currency'];
  const details = workbook.addWorksheet('Bookings');
  details.addRow(headings);
  for (const item of items) details.addRow([
    item.bookingCode, item.driverDisplayName, item.stationName, item.connectorCode,
    wallTime(item.startAt), wallTime(item.endAt),
    (Date.parse(item.endAt) - Date.parse(item.startAt)) / 60_000,
    item.status, item.cancellationReason ?? '', item.totalAmount, item.currency,
  ]);
  const widths = [25, 30, 35, 24, 24, 24, 29, 20, 28, 23, 16];
  details.columns.forEach((column, i) => { column.width = widths[i]; });
  [5, 6].forEach((index) => { details.getColumn(index).numFmt = 'dd/mm/yyyy hh:mm:ss'; });
  [7, 10].forEach((index) => { details.getColumn(index).numFmt = '#,##0.##'; });
  details.autoFilter = { from: { row: 1, column: 1 }, to: { row: items.length + 1, column: 11 } };
  const summary = workbook.addWorksheet('Summary');
  summary.addRows([
    [vi ? 'Thông tin' : 'Metric', vi ? 'Giá trị' : 'Value'],
    [vi ? 'Thời điểm xuất' : 'Generated at', wallTime(now)],
    [vi ? 'Múi giờ' : 'Timezone', 'Asia/Ho_Chi_Minh'],
    ['stationId', filter.stationId ?? ''], ['connectorId', filter.connectorId ?? ''],
    ['from', filter.from ? wallTime(filter.from) : ''], ['to (exclusive)', filter.to ? wallTime(filter.to) : ''],
    ['status', filter.status ?? ''], ['windowMode', filter.windowMode ?? 'OVERLAP'],
    ['sort', filter.sort ?? 'startAt,desc'],
    [vi ? 'Tổng số booking' : 'Total bookings', items.length],
    ...['PENDING', 'CONFIRMED', 'CHECKED_IN', 'CHARGING', 'COMPLETED', 'CANCELLED', 'EXPIRED']
      .map((status) => [status, items.filter((item) => item.status === status).length]),
    [vi ? 'Ghi chú' : 'Note', vi
      ? 'Dữ liệu demo. Giá trị booking không phải doanh thu thực thu. Thời lượng là thời gian đặt chỗ.'
      : 'Demo data. Booking value is not collected revenue. Duration is the booked time.'],
  ]);
  [2, 6, 7].forEach((row) => { summary.getRow(row).getCell(2).numFmt = 'dd/mm/yyyy hh:mm:ss'; });
  summary.getColumn(1).width = 35; summary.getColumn(2).width = 100;
  for (const sheet of [details, summary]) {
    sheet.views = [{ state: 'frozen', ySplit: 1 }];
    sheet.getRow(1).eachCell((cell) => {
      cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
      cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF004C4C' } };
    });
  }
  const buffer = await workbook.xlsx.writeBuffer();
  return {
    blob: new Blob([new Uint8Array(buffer)], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }),
    filename: `chargeops-bookings-demo-${now.toISOString().slice(0, 10)}.xlsx`,
  };
}
